import React, { useCallback, useEffect, useRef, useState } from 'react';
import './App.css';

type Connection = {
  connect(): void;
  disconnect(): void;
};

type ConnectionEvents = {
  onStatus: (status: string) => void;
  onActiveCount: (count: number) => void;
  onEvent: (event: string) => void;
  onMessage: () => void;
};

const CONNECT_DELAY_MS = 300;
const MESSAGE_INTERVAL_MS = 200;

const activeConnections = new Set<symbol>();

function createConnection(roomId: string, events: ConnectionEvents): Connection {
  let token: symbol | null = null;
  let connectTimer: number | null = null;
  let messageTimer: number | null = null;

  return {
    connect() {
      if (token !== null || connectTimer !== null) return;
      events.onStatus('Connecting to ' + roomId);
      connectTimer = window.setTimeout(() => {
        connectTimer = null;
        token = Symbol(roomId);
        activeConnections.add(token);
        events.onStatus('Connected to ' + roomId);
        events.onActiveCount(activeConnections.size);
        events.onEvent('Connected to ' + roomId);
        messageTimer = window.setInterval(events.onMessage, MESSAGE_INTERVAL_MS);
      }, CONNECT_DELAY_MS);
    },
    disconnect() {
      // An attempt that never went live leaves nothing to report.
      if (connectTimer !== null) {
        window.clearTimeout(connectTimer);
        connectTimer = null;
        events.onStatus('Disconnected');
        return;
      }
      if (token === null) return;
      if (messageTimer !== null) window.clearInterval(messageTimer);
      messageTimer = null;
      activeConnections.delete(token);
      token = null;
      events.onStatus('Disconnected');
      events.onActiveCount(activeConnections.size);
      events.onEvent('Disconnected from ' + roomId);
    }
  };
}

function ConnectionPanel({
  roomId,
  muted,
  onActiveCount,
  onEvent
}: {
  roomId: string;
  muted: boolean;
  onActiveCount: (count: number) => void;
  onEvent: (event: string) => void;
}) {
  const [status, setStatus] = useState('Disconnected');
  const [messageCount, setMessageCount] = useState(0);

  // The connection reads the latest setting through this ref, so muting never reconnects.
  const mutedRef = useRef(muted);
  useEffect(() => {
    mutedRef.current = muted;
  }, [muted]);

  useEffect(() => {
    const connection = createConnection(roomId, {
      onStatus: setStatus,
      onActiveCount,
      onEvent,
      onMessage: () => {
        if (!mutedRef.current) setMessageCount((count) => count + 1);
      }
    });
    connection.connect();
    return () => connection.disconnect();
  }, [roomId, onActiveCount, onEvent]);

  return (
    <div className="panel">
      <div className="label connection-status">{status}</div>
      <div className="hint">Messages counted: <span className="message-count">{messageCount}</span></div>
    </div>
  );
}

export default function App() {
  const [mounted, setMounted] = useState(true);
  const [roomId, setRoomId] = useState('general');
  const [renderCount, setRenderCount] = useState(0);
  const [activeCount, setActiveCount] = useState(0);
  const [muted, setMuted] = useState(false);
  const [events, setEvents] = useState<string[]>([]);

  const addEvent = useCallback((event: string) => {
    setEvents((current) => [...current, event]);
  }, []);

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Effect Lifecycle</h1>
        <p className="subtitle">Each setup owns one matching cleanup, even when connecting takes time.</p>

        <div className="stats">
          <div className="stat"><span className="k">Room</span><span className="v room-value">{roomId}</span></div>
          <div className="stat"><span className="k">Active connections</span><span className="v active-count">{activeCount}</span></div>
          <div className="stat"><span className="k">Unrelated renders</span><span className="v render-count">{renderCount}</span></div>
        </div>

        <div className="actions">
          <button className="btn rerender-button" onClick={() => setRenderCount((count) => count + 1)}>Re-render</button>
          <button className="btn ghost room-button" onClick={() => setRoomId((room) => room === 'general' ? 'design' : 'general')}>Switch room</button>
          <button className="btn ghost mount-button" onClick={() => setMounted((value) => !value)}>Toggle panel</button>
          <button className="btn ghost mute-button" aria-pressed={muted} onClick={() => setMuted((value) => !value)}>
            {muted ? 'Unmute' : 'Mute'}
          </button>
        </div>

        {mounted
          ? <ConnectionPanel roomId={roomId} muted={muted} onActiveCount={setActiveCount} onEvent={addEvent} />
          : <div className="panel"><div className="label connection-status">Unmounted</div></div>}

        <ol className="event-log">
          {events.map((event, index) => <li key={index}>{event}</li>)}
        </ol>
      </section>
    </main>
  );
}

